lemmas.∘-resp-≈:
{A = A₁ : Obj} {B : Obj} {C = i₁ : Obj}
{f = j : B ⇒ i₁} {h = k : B ⇒ i₁}
{g = g₁ : A₁ ⇒ B} {i = i₂ : A₁ ⇒ B} →
j ≈ k → g₁ ≈ i₂ → j ∘ g₁ ≈ k ∘ i₂

lemmas.cancelʳ:
{i.Y = A₁ : Obj} {i.X = B : Obj} {h = i₁ : A₁ ⇒ B}
{i = j : B ⇒ A₁} →
i₁ ∘ j ≈ id → {f.Y : Obj} {f : B ⇒ f.Y} → (f ∘ i₁) ∘ j ≈ f

